#!/usr/bin/env python3
"""Writes one square PNG image of a .ico file as a C++ source with raw RGBA pixels.

Linux counterpart of the icon resource in assets/windows/prime_port.rc: the SDL window
takes RGBA pixels, and decoding at build time keeps the runtime free of an image loader.
Only the PNG entries this project's icon uses are supported (8-bit RGB/RGBA, no interlace).

Usage: ico_to_rgba_source.py ICON SIZE OUTPUT.cpp
"""
import struct
import sys
import zlib


def find_png(icon, size):
    reserved, kind, count = struct.unpack_from('<HHH', icon, 0)
    if reserved != 0 or kind != 1:
        sys.exit('not an icon file')
    for index in range(count):
        width, height, _, _, _, _, length, offset = struct.unpack_from('<BBBBHHII', icon, 6 + 16 * index)
        if (width or 256) == size and (height or 256) == size:
            data = icon[offset:offset + length]
            if data[:8] != b'\x89PNG\r\n\x1a\n':
                sys.exit(f'the {size}x{size} entry is not a PNG image')
            return data
    sys.exit(f'no {size}x{size} entry in the icon')


def decode_png(data):
    position, idat, header = 8, b'', None
    while position < len(data):
        length, chunk = struct.unpack_from('>I4s', data, position)
        body = data[position + 8:position + 8 + length]
        if chunk == b'IHDR':
            header = struct.unpack('>IIBBBBB', body)
        elif chunk == b'IDAT':
            idat += body
        position += 12 + length
    width, height, depth, color, _, _, interlace = header
    if depth != 8 or color not in (2, 6) or interlace != 0:
        sys.exit('unsupported PNG layout (8-bit RGB or RGBA without interlace expected)')
    channels = 4 if color == 6 else 3
    stride = width * channels
    raw = zlib.decompress(idat)
    rows, previous = [], bytearray(stride)
    for y in range(height):
        kind = raw[y * (stride + 1)]
        row = bytearray(raw[y * (stride + 1) + 1:(y + 1) * (stride + 1)])
        for x in range(stride):
            left = row[x - channels] if x >= channels else 0
            up = previous[x]
            corner = previous[x - channels] if x >= channels else 0
            if kind == 1:
                row[x] = (row[x] + left) & 0xFF
            elif kind == 2:
                row[x] = (row[x] + up) & 0xFF
            elif kind == 3:
                row[x] = (row[x] + (left + up) // 2) & 0xFF
            elif kind == 4:
                estimate = left + up - corner
                pa, pb, pc = abs(estimate - left), abs(estimate - up), abs(estimate - corner)
                row[x] = (row[x] + (left if pa <= pb and pa <= pc else up if pb <= pc else corner)) & 0xFF
            elif kind != 0:
                sys.exit(f'bad PNG filter {kind}')
        rows.append(row)
        previous = row
    pixels = bytearray()
    for row in rows:
        if channels == 4:
            pixels += row
        else:
            for x in range(width):
                pixels += row[x * 3:x * 3 + 3] + b'\xff'
    return width, height, bytes(pixels)


def main():
    icon_path, size, output = sys.argv[1], int(sys.argv[2]), sys.argv[3]
    width, height, pixels = decode_png(find_png(open(icon_path, 'rb').read(), size))
    lines = [', '.join(str(b) for b in pixels[i:i + 24]) for i in range(0, len(pixels), 24)]
    text = (
        '// Generated by cmake/ico_to_rgba_source.py from the Windows icon. Do not edit.\n'
        '#include <cstdint>\n\n'
        f'extern "C" const uint32_t g_productWindowIconSize = {width};\n'
        f'extern "C" const uint8_t g_productWindowIconRgba[{len(pixels)}] = {{\n    '
        + ',\n    '.join(lines) + '\n};\n'
    )
    if width != height:
        sys.exit('the icon must be square')
    with open(output, 'w', encoding='ascii', newline='\n') as file:
        file.write(text)


if __name__ == '__main__':
    main()
